#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("USAGE\n");
        return 1;
    }
    char *pattern = argv[1];
    char *string = argv[2];
    int match = 0;
    for (int i = 0; i < strlen(string); i++) {
        if (pattern[0] == '*') {
            match = 1;
            break;
        }
        if (pattern[0] == '?') {
            pattern++;
            continue;
        }
        if (pattern[0] != string[i]) {
            match = 0;
            break;
        }
        pattern++;
    }
    if (match) {
        printf("MATCH\n");
    } else {
        printf("NO_MATCH\n");
    }
    return 0;
}
